#include <bits/stdc++.h>
using namespace std;

using ll = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll n;
    cin >> n;

    if (n == 1) {
        cout << "1 0\n";
        return 0;
    }

    ll value = n;
    ll radical = 1;
    vector<int> exponents;

    for (ll p = 2; p <= value / p; ++p) {
        if (value % p == 0) {
            int exponent = 0;
            radical *= p;

            while (value % p == 0) {
                value /= p;
                ++exponent;
            }

            exponents.push_back(exponent);
        }
    }

    if (value > 1) {
        radical *= value;
        exponents.push_back(1);
    }

    int maximumExponent = *max_element(exponents.begin(), exponents.end());
    int targetExponent = 1;
    int operations = 0;

    while (targetExponent < maximumExponent) {
        targetExponent *= 2;
        ++operations;
    }

    for (int exponent : exponents) {
        if (exponent != targetExponent) {
            ++operations;
            break;
        }
    }

    cout << radical << ' ' << operations << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;

vector<pair<ll, int>> prime_fac(ll n)
{
    vector<pair<ll, int>> factors;

    for (ll p = 2; p <= n / p; ++p)
    {
        if (n % p != 0)
            continue;

        int exponent = 0;
        while (n % p == 0)
        {
            n /= p;
            ++exponent;
        }
        factors.emplace_back(p, exponent);
    }

    if (n > 1)
        factors.emplace_back(n, 1);

    return factors;
}

int main()
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll n;
    cin >> n;

    if (n == 1)
    {
        cout << "1 0\n";
        return 0;
    }

    ll answer = 1;
    int maxExponent = 0;
    int firstExponent = -1;
    bool differentExponents = false;

    for (const auto &[prime, exponent] : prime_fac(n))
    {
        answer *= prime;
        maxExponent = max(maxExponent, exponent);

        if (firstExponent == -1)
            firstExponent = exponent;
        else if (firstExponent != exponent)
            differentExponents = true;
    }

    if (maxExponent == 1)
    {
        cout << n << " 0\n";
        return 0;
    }

    int power = 1;
    int operations = 0;

    while (power < maxExponent)
    {
        power <<= 1;
        ++operations;
    }

    if (power != maxExponent || differentExponents)
        ++operations;

    cout << answer << ' ' << operations << '\n';
    return 0;
}

