#include <bits/stdc++.h>

using namespace std;

#define endl "\n"
#define ll long long int
#define ull unsigned long long int

vector<bool> is_prime;

void sieve(int limit)
{
    is_prime.assign(limit + 1, true);

    if (limit >= 0) is_prime[0] = false;
    if (limit >= 1) is_prime[1] = false;

    for (int i = 2; 1LL * i * i <= limit; ++i)
    {
        if (is_prime[i])
        {
            for (long long j = 1LL * i * i; j <= limit; j += i)
            {
                is_prime[j] = false;
            }
        }
    }
}

vector<int> get_primes(int limit)
{
    vector<int> primes;
    sieve(limit);

    for (int i = 2; i <= limit; ++i)
    {
        if (is_prime[i])
        {
            primes.push_back(i);
        }
    }

    return primes;
}

vector<pair<int, int>> prime_fac(int n)
{
    vector<int> primes = get_primes(n);
    vector<pair<int, int>> factors;

    for (size_t i = 0; i < primes.size() &&
                       1LL * primes[i] * primes[i] <= n; ++i)
    {
        int count = 0;

        while (n % primes[i] == 0)
        {
            n /= primes[i];
            ++count;
        }

        if (count > 0)
        {
            factors.emplace_back(primes[i], count);
        }
    }

    if (n > 1)
    {
        factors.emplace_back(n, 1);
    }

    return factors;
}

int main()
{
    ll n;
    cin >> n;

    if (n == 1)
    {
        cout << 1 << " " << 0 << endl;
        return 0;
    }

    ll ans = 1;
    int maximumExponent = 0;
    int firstExponent = -1;
    bool differentExponents = false;

    for (const auto& factor : prime_fac(static_cast<int>(n)))
    {
        if (firstExponent == -1)
        {
            firstExponent = factor.second;
        }
        else if (firstExponent != factor.second)
        {
            differentExponents = true;
        }

        maximumExponent = max(maximumExponent, factor.second);
        ans *= factor.first;
    }

    if (maximumExponent == 1)
    {
        cout << n << " " << 0 << endl;
        return 0;
    }

    int power = 1;
    int operations = 0;

    while (power < maximumExponent)
    {
        power <<= 1;
        ++operations;
    }

    if (differentExponents || power != maximumExponent)
    {
        ++operations;
    }

    cout << ans << " " << operations << endl;

    return 0;
}

